from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from constance import config

class ClientRateLimitOverrideView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, client_id):
        if not request.user.is_superuser:
            return Response({"detail": "Superuser privileges required to override client rate limits"}, status=403)

        tier_cap = request.data.get("custom_rpm")
        setting_key = f"RATE_LIMIT_OVERRIDE_{client_id}"

        if not hasattr(config, setting_key):
            return Response({"detail": "No custom rate limit slot available"}, status=400)

        setattr(config, setting_key, int(tier_cap))
        return Response({"client_id": client_id, "custom_rpm": tier_cap})
